import React from 'react';
import { Link } from 'react-router-dom';
import './DashboardCustomer.css';

function DashboardCustomer() {
  const categories = ['Desain', 'Editing', 'Tulisan', 'Teknologi'];
  const orders = [
    { title: 'Desain Logo Cafe Kopi Kekinian', price: 'Rp 250k', status: 'Aktif', deadline: 'Besok, 17:00', worker: 'Farhan M.', role: 'Desainer Grafis' },
    { title: 'Video Reels Promosi Launching Produk', price: 'Rp 500k', status: 'Dikerjakan', deadline: '3 Hari Lagi', worker: 'Sarah K.', role: 'Video Editor' }
  ];

  return (
    <div className="dashboard-customer">
      <header className="dashboard-header">
        <div className="header-top">
          <h1>WORKIE</h1>
          <div className="header-icons"><span>🔔</span><span>👤</span></div>
        </div>
        <div className="greeting"><p>Selamat Pagi,</p><h2>Halo, Andi Wijaya!</h2></div>
      </header>
      <div className="search-section">
        <div className="search-bar"><span>🔍</span><input type="text" placeholder="Kamu butuh bantuan apa?" /></div>
        <button className="btn-order">+ Buat Order Instan</button>
        <p className="ai-hint">Ketik kebutuhan kerjamu, AI kami buatkan deskripsinya!</p>
      </div>
      <div className="categories-section">
        <h3>Kategori Terpopuler</h3>
        <div className="category-chips">{categories.map((cat, i) => (<span key={i} className="chip">{cat}</span>))}</div>
      </div>
      <div className="orders-section">
        <div className="section-header"><h3>Order Anda Saat Ini</h3><Link to="/">Lihat Semua</Link></div>
        {orders.map((order, i) => (
          <div key={i} className="order-card">
            <span className={`status-badge ${order.status.toLowerCase()}`}>{order.status}</span>
            <h4>{order.title}</h4>
            <p className="price">{order.price}</p>
            <div className="worker-info"><span>{order.worker}</span><span className="role">{order.role}</span><span className="deadline">📅 {order.deadline}</span></div>
          </div>
        ))}
      </div>
      <div className="bottom-nav">
        <Link to="/dashboard-customer" className="nav-item active">🏠 Home</Link>
        <Link to="/" className="nav-item">📋 Orders</Link>
        <Link to="/" className="nav-item">💬 Chat</Link>
        <Link to="/" className="nav-item">💳 Wallet</Link>
        <Link to="/" className="nav-item">👤 Profile</Link>
      </div>
    </div>
  );
}

export default DashboardCustomer;
